{
  "name": "compare_countries_by_world_bank_indicator",
  "kind": "workflow",
  "description": "Fetches the latest World Bank indicator value (default population) for a list of countries and ranks them.",
  "signature": {
    "in": "{\"type\":\"object\",\"properties\":{\"countries\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}},\"indicator\":{\"type\":\"string\"}},\"required\":[\"countries\"]}",
    "out": "output of s2"
  },
  "steps": [
    {
      "id": "s1",
      "uses": "fetch_world_bank_indicator",
      "foreach": "$input.countries",
      "inputs": [
        {
          "param": "country",
          "source": "$item"
        },
        {
          "param": "indicator",
          "source": "$input.indicator"
        }
      ]
    },
    {
      "id": "s2",
      "uses": "rank_countries_by_value",
      "foreach": null,
      "inputs": [
        {
          "param": "records",
          "source": "$steps.s1.items"
        }
      ]
    }
  ],
  "output_step": "s2",
  "permissions": {
    "net": [
      "api.worldbank.org"
    ],
    "llm": false
  },
  "budget": {
    "max_tokens_per_run": 0
  },
  "lineage": {
    "created_by": "factory",
    "uses": [
      "fetch_world_bank_indicator@v1",
      "rank_countries_by_value@v1"
    ]
  },
  "example_input": "{\"countries\":[\"IN\",\"CN\",\"US\",\"ID\"],\"indicator\":\"SP.POP.TOTL\"}",
  "purpose": "make a bot to compare countries populations",
  "version": 1,
  "headline": "Among the countries compared, {largest.country_name} ranks first with {largest.value} ({largest.year}), while {smallest.country_name} ranks last with {smallest.value}, making the largest about {ratio} times the smallest.",
  "examples": [
    "Which is bigger by population, India or China?",
    "Compare the populations of the US, Brazil and Japan",
    "Rank Germany, France, Italy and Spain by number of people"
  ],
  "voice": "golem",
  "manual_minutes": 8.0,
  "manual_basis": "Fetch population data from World Bank API for 4 countries, organize in spreadsheet, sort by value, format comparison table."
}

